"""Локализация: язык интерфейса (ru/en) и язык результатов ИИ (ru/en/de/it/it-en)."""

# Как называется язык в переключателях
UI_LANGS = {"ru": "Русский", "en": "English", "it": "Italiano", "de": "Deutsch"}
OUTPUT_LANGS = {"ru": "Русский", "en": "English", "de": "Deutsch",
                "it": "Italiano", "it-en": "Italiano + English"}

# Инструкция модели, на каком языке писать результаты (оценки, правки, дайджест)
OUTPUT_INSTRUCTION = {
    "ru": "на русском языке",
    "en": "in English",
    "de": "auf Deutsch",
    "it": "in italiano",
    "it-en": ("in italiano E POI in inglese — ogni testo prima in italiano, poi la "
              "stessa frase in inglese, separati da « / ». Esempio: «Ottima "
              "corrispondenza con il profilo / Great match for the profile». "
              "NON scrivere in russo. Sii CONCISO: ogni metà max 2 frasi brevi, "
              "perché il testo bilingue è lungo il doppio"),
}


def out_lang(cfg: dict) -> str:
    return OUTPUT_INSTRUCTION.get(cfg.get("ui", {}).get("output_lang", "ru"), OUTPUT_INSTRUCTION["ru"])


