def t(lang: str, key: str) -> str:
    lang = (lang or "ru").split("-")[0]  # "it-en" → заголовки по-итальянски
    entry = TR.get(key)
    if not entry:
        return key
    return entry.get(lang) or entry.get("ru") or key
